using AcxiomCRM.Data;using AcxiomCRM.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Api;[ApiController,Route("api/leads"),Authorize] public class LeadsApiController:ControllerBase{private readonly ApplicationDbContext _db;public LeadsApiController(ApplicationDbContext db){_db=db;}[HttpGet]public async Task<IActionResult> Get()=>Ok(await _db.Leads.OrderByDescending(x=>x.CreatedDate).Select(x=>new{x.Id,x.LeadCode,x.LeadName,x.Email,x.Phone,x.CompanyName,x.Source,x.Status,x.ExpectedValue,x.AssignedTo}).ToListAsync());[HttpPost]public async Task<IActionResult> Create(Lead l){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(string.IsNullOrWhiteSpace(l.LeadCode))l.LeadCode="LED-"+Guid.NewGuid().ToString("N")[..8].ToUpper();l.Id=0;l.CreatedBy=User.Identity?.Name;_db.Leads.Add(l);await _db.SaveChangesAsync();return Created($"/api/leads/{l.Id}",new{id=l.Id,l.LeadCode,l.LeadName,l.Status});}}
